def calculate_blur_score(image_path):
    image = cv2.imread(str(image_path))

    if image is None:
        return None

    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)

    score = cv2.Laplacian(
        gray, cv2.CV_64F
    ).var()

    return float(score)


results = []

for folder in FOLDERS:
    folder_path = DATA_DIR / folder

    if not folder_path.exists():
        print(f"Folder tidak ditemukan: {folder_path}")
        continue

    for image_path in folder_path.rglob("*"):
        if image_path.suffix.lower() not in IMAGE_EXTENSIONS:
            continue

        score = calculate_blur_score(image_path)

        results.append({
            "folder": folder,
            "filename": image_path.name,
            "path": str(image_path),
            "blur_score": score,
            "status": (
                "unreadable" if score is None else "analyzed"
            )
        })

df = pd.DataFrame(results)

df.to_csv("blur_report.csv", index=False)

valid_scores = df.loc[
    df["blur_score"].notna(), "blur_score"
]

print("Total image:", len(df))
print("Image blur:", df["blur_score"].isna().sum())

if not valid_scores.empty:
    print("\nBlur score:")
    print(valid_scores.describe())

print("\nReport saved to blur_report.csv")
